import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] v = new int[4];

        for (int i = 0; i < 4; i++) {
            v[i] = sc.nextInt();
        }

        int ans = Integer.MAX_VALUE;

        for (int i = 0; i < 4; i++) {
            for (int j = i + 1; j < 4; j++) {
                int sum1 = v[i] + v[j];
                int sum2 = 0;

                for (int k = 0; k < 4; k++) {
                    if (k != i && k != j) {
                        sum2 += v[k];
                    }
                }

                ans = Math.min(ans, Math.abs(sum1 - sum2));
            }
        }

        System.out.println(ans);
    }
}
